CREATE TABLE departments(department_id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,department_name VARCHAR2(100) NOT NULL UNIQUE,description VARCHAR2(500));
CREATE TABLE positions(position_id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,position_name VARCHAR2(100) NOT NULL UNIQUE,salary_rate NUMBER(10,2) NOT NULL);
CREATE TABLE accounts(account_id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR2(50) NOT NULL UNIQUE,password VARCHAR2(255) NOT NULL,role VARCHAR2(20) NOT NULL CHECK(role IN('admin','hr','manager','employee')),status VARCHAR2(10) DEFAULT 'active' NOT NULL CHECK(status IN('active','inactive','locked')));
CREATE TABLE employees(employee_id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id NUMBER(10) UNIQUE REFERENCES accounts,department_id NUMBER(10) NOT NULL REFERENCES departments,position_id NUMBER(10) NOT NULL REFERENCES positions,manager_id NUMBER(10) REFERENCES employees,first_name VARCHAR2(100) NOT NULL,last_name VARCHAR2(100) NOT NULL,email VARCHAR2(150) NOT NULL UNIQUE,phone VARCHAR2(20),address VARCHAR2(500),hire_date DATE NOT NULL,day_off NUMBER(3) DEFAULT 10 NOT NULL,employment_status VARCHAR2(10) DEFAULT 'active' NOT NULL CHECK(employment_status IN('active','on_leave','resigned')));
CREATE TABLE reports(report_id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id NUMBER(10) NOT NULL REFERENCES employees,report_type VARCHAR2(50) NOT NULL,created_date TIMESTAMP DEFAULT SYSTIMESTAMP,data CLOB);
CREATE TABLE resignations(resignation_id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id NUMBER(10) NOT NULL REFERENCES employees,request_date DATE DEFAULT SYSDATE NOT NULL,effective_date DATE NOT NULL,reason VARCHAR2(1000),status VARCHAR2(10) DEFAULT 'approved' NOT NULL CHECK(status IN('pending','approved','rejected','cancelled')))
